function BeforeShowAdd(&$xt, &$templatefile, $pageObject)
{

		/**
 * EVENTO: BeforeDisplay (ADD)
 * MÓDULO: Solicitud de Vacaciones (RRHH)
 *
 * OBJETIVO:
 * Ocultar campos que NO deben ser visibles ni editables
 * por el usuario final en el formulario de alta (ADD).
